```c++
class Expensive {
public:
  Expensive() { std::cout << "Constructor called\n"; }
  Expensive(const Expensive& other) { std::cout << "Copy constructor called\n"; }
  ~Expensive() { std::cout << "Destructor called\n"; }
};

Expensive createExpensiveObject() {
  Expensive obj;
  return obj; // RVO likely here
}

Expensive createExpensiveObjectNamed(Expensive obj) {
  return obj; // NRVO likely here
}
